// Render GEO JSON to Telegram MarkdownV2 with required character escaping.
const esc = (s = '') => String(s).replace(/[_*\[\]()~`>#+\-=|{}.!]/g, '\\$&');
const g = $json;
const body = [
  '*🎯 Goal*\n' + esc(g.goal),
  '*🛠 Execution*\n' + esc(g.execution),
  '*💡 Outcome*\n' + esc(g.outcome),
  '*🔄 Historical Evolution*\n' + esc(g.historical_evolution),
].join('\n\n');
return [{ json: { markdown: body } }];
